#include <bits/stdc++.h>
using namespace std;
int lis(const vector<int>&a){
    int n=a.size(); vector<int> dp(n,1); int r=0;
    for(int i=0;i<n;i++){ for(int j=0;j<i;j++) if(a[j]<a[i]) dp[i]=max(dp[i],dp[j]+1); r=max(r,dp[i]);}
    return r;
}
int main(){
    int n=6;
    vector<int> p(n); iota(p.begin(),p.end(),1);
    vector<vector<int>> perms;
    do{ perms.push_back(p);}while(next_permutation(p.begin(),p.end()));
    int m=perms.size();
    vector<int> LP(m);
    for(int i=0;i<m;i++) LP[i]=lis(perms[i]);
    // store witness
    map<tuple<int,int,int>,pair<int,int>> wit;
    for(int ip=0; ip<m; ip++){
        vector<int> posP(n+1);
        for(int i=0;i<n;i++) posP[perms[ip][i]]=i;
        int x=LP[ip];
        for(int iq=0; iq<m; iq++){
            vector<char> vis(n+1,0); int cyc=0;
            for(int v=1;v<=n;v++) if(!vis[v]){ cyc++; int u=v; while(!vis[u]){vis[u]=1; u=perms[iq][posP[u]];} }
            int y=LP[iq];
            auto key=make_tuple(x,y,cyc);
            if(!wit.count(key)) wit[key]={ip,iq};
        }
    }
    auto print=[&](int x,int y,int k){
        auto it=wit.find(make_tuple(x,y,k));
        if(it==wit.end()){ printf("x=%d y=%d k=%d: NONE\n",x,y,k); return;}
        printf("x=%d y=%d k=%d: P=",x,y,k);
        for(int v: perms[it->second.first]) printf("%d ",v);
        printf(" Q=");
        for(int v: perms[it->second.second]) printf("%d ",v);
        printf("\n");
    };
    // print k=1 for all x,y
    for(int x=1;x<=n;x++)for(int y=1;y<=n;y++) print(x,y,1);
    printf("---- kmax-ish\n");
    for(int x=1;x<=n;x++)for(int y=1;y<=n;y++){
        int d=abs(x-y); int kmax=n-(d+1)/2;
        if(kmax>=1) print(x,y,kmax);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int lds(const vector<int>&a){
    int n=a.size(); vector<int> dp(n,1); int r=0;
    for(int i=0;i<n;i++){ for(int j=0;j<i;j++) if(a[j]>a[i]) dp[i]=max(dp[i],dp[j]+1); r=max(r,dp[i]);}
    return r;
}
int main(){
    for(int n=1;n<=6;n++){
        vector<int> p(n); iota(p.begin(),p.end(),1);
        map<pair<int,int>,vector<int>> wit;
        do{
            vector<char> vis(n+1,0); int cyc=0;
            for(int v=1;v<=n;v++) if(!vis[v]){ cyc++; int u=v; while(!vis[u]){vis[u]=1; u=p[u-1];} }
            int b=lds(p);
            if(!wit.count({b,cyc})) wit[{b,cyc}]=p;
        }while(next_permutation(p.begin(),p.end()));
        printf("n=%d\n",n);
        for(auto&kv:wit){
            printf("  b=%d c=%d :",kv.first.first,kv.first.second);
            for(int v:kv.second) printf(" %d",v);
            printf("\n");
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int lis(const vector<int>&a){int n=a.size();vector<int>dp(n,1);int r=0;for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(a[j]<a[i])dp[i]=max(dp[i],dp[j]+1);r=max(r,dp[i]);}return r;}
int main(){
    for(int n=1;n<=7;n++){
        vector<int> p(n); iota(p.begin(),p.end(),1);
        // existence of P with LIS(P)=a and LIS(shift_t(P))=b for some t
        map<pair<int,int>,vector<int>> sol; // (a,b)->P for best t
        do{
            int a=lis(p);
            for(int t=1;t<n;t++){
                vector<int> q(n); for(int i=0;i<n;i++){ q[i]=p[i]+t; if(q[i]>n)q[i]-=n; }
                int b=lis(q);
                if(!sol.count({a,b})) sol[{a,b}]=p;
            }
        }while(next_permutation(p.begin(),p.end()));
        printf("n=%d:\n",n);
        for(int a=1;a<=n;a++){ printf("  a=%d:",a); for(int b=1;b<=n;b++) printf(" %d", (int)sol.count({a,b})); printf("\n"); }
    }
    return 0;
}
